  "items:normal_log:description": "刚被斧头砍下的青绿木料，还带着一丝松脂气味。是每个拓荒者最先砍伐的燃料与建材。",
  "items:oak_log:description": "比普通木料更坚韧，风干也更慢。每当横梁需要真正承重时，New Haven的木匠都会选它。",
  "items:blackwood_log:description": "取自边域古老林地的深纹木材，比橡木更沉，锯起来也更费劲。",
  "items:ironbark_log:description": "树皮被山下涌动的某种力量硬化得近乎金属。敲击时铿然作响，而非碎裂。",
  "items:bloodoak_log:description": "生长在古战场土壤上的橡木，纹理暗如干涸的血迹，握在手中分量倍增。",
  "items:shadowpine_log:description": "生长在阳光几乎照不到之处的松木，即使刚砍下也苍白冰凉。",
  "items:ashfen_log:description": "取自沼地焦黑边缘的木料，带着永远洗不净的烟灰痕迹。",
  "items:raw_anglerfish:description": "长相丑陋、自带诱饵的渔获，最好直接吃掉，别细看。",
  "items:raw_crypteel:description": "从淹没墓穴的水中捞出的鳗鱼，冰冷滑腻，怎么也不肯安分。",
  "items:crude_bone:description": "一根价值不大的碎骨，但在New Haven，每一点边角料都能派上用场。",
  "items:grimwheat_seed:description": "耐旱谷种，专为大多数作物都拒绝生长的土地培育。",
  "items:graywort:description": "一种毫不起眼的杂草，长在别的植物都不愿扎根之处，用处却比外表看起来大得多。",
  "items:gloomspore:description": "在黑暗中微微发光的真菌孢子，趁其扩散之前便被采集。",
  "items:bloodbeet_seed:description": "一种块根的种子，还没染红锅子就先染红了手指。",
  "items:wraithcap_seed:description": "一种苍白蘑菇的种子，仿佛会躲避提灯的光。",
  "items:stolen_coinpurse:description": "陌生人的钱袋，比对方上次查看时轻了不少。",
  "items:cutpurse_trinket:description": "顺手连钱一起摸走的小饰物，对销赃者的价值比对原主人还高。",
  "items:guard_insignia:description": "一枚能打开不该打开之门的徽章，只要没人太仔细端详佩戴者的脸。",
  "items:ledger_page:description": "从某人账本上撕下的一页，记着一堆本不该公开的债务。",
