  "quests:daily_h_craft_steel_arrows_25:name": "钢铁补给",
  "quests:daily_h_gather_150:name": "满载而归",
  "quests:daily_h_kill_bramble_witch:name": "焚巫",
  "quests:daily_h_kill_forest_warden:name": "守望者之陨",
  "quests:daily_h_kill_kill_total_30:name": "战斗老手",
  "quests:daily_h_kill_moss_golem:name": "碎石者",
  "quests:daily_h_kill_spectral_stag:name": "猎魂",
  "quests:daily_h_smelt_adamantium_4:name": "精金锭",
  "quests:daily_h_smelt_mithril_5:name": "秘银轮值",
  "quests:daily_m_craft_iron_arrows_20:name": "铁料补给",
  "quests:daily_m_gather_80:name": "满袋",
  "quests:daily_m_kill_goblins_20:name": "剔除哥布林",
  "quests:daily_m_kill_mire_crawler:name": "沼泽净化者",
  "quests:daily_m_kill_pitch_beetle:name": "甲虫克星",
  "quests:daily_m_kill_shaman_8:name": "让萨满噤声",
  "quests:daily_m_kill_thorn_wolf:name": "狼群守望",
  "quests:daily_m_smelt_blacksteel_4:name": "黑暗合金",
  "quests:daily_m_smelt_steel_6:name": "钢铁生产",
  "quests:daily_ma_craft_runite_arrows_20:name": "符文矿补给",
  "quests:daily_ma_kill_ember_elemental_30:description": "熄灭 30 个在熔渣坑肆虐的余烬元素。",
  "quests:daily_ma_kill_ember_elemental_30:name": "熄烬者",
  "quests:daily_ma_kill_frost_hexer_15:description": "让 15 名冰霜咒师噤声，趁其冰川诅咒尚未蔓延全坑。",
  "quests:daily_ma_kill_frost_hexer_15:name": "冰封寂静",
  "quests:daily_ma_kill_frost_hound_20:description": "猎杀 20 只在冰封熔渣坑深处游荡的霜猎犬。",
  "quests:daily_ma_kill_frost_hound_20:name": "破群者",
  "quests:daily_ma_kill_iron_revenant_25:description": "驱逐 25 只作祟于熔渣坑最深处密室的钢铁亡魂。",
  "quests:daily_ma_kill_iron_revenant_25:name": "猎捕铁魂",
  "quests:daily_ma_kill_slag_kobold_40:description": "消灭 40 只在熔渣坑肆虐的熔渣狗头人。",
  "quests:daily_ma_kill_slag_kobold_40:name": "剿灭狗头人",
  "quests:daily_ma_kill_total_60:name": "旷世杀戮",
  "quests:daily_ma_smelt_bloodiron_3:name": "血金属",
  "quests:daily_ma_smelt_runite_4:name": "符文矿熔炉",
  "quests:daily_ve_cook_shrimp:name": "码头早餐",
  "quests:daily_ve_craft_bronze_bar:name": "青铜基础",
  "quests:daily_ve_fletch_shafts:name": "皮革批次",
  "quests:daily_ve_gather_any_10:name": "跑腿信使",
  "quests:daily_ve_gather_logs:name": "清晨柴堆",
  "quests:daily_ve_kill_boar_5:name": "野猪袭扰",
  "quests:daily_ve_kill_chickens:name": "农场剔除",
  "quests:daily_ve_kill_cows:name": "削减畜群",
  "quests:daily_ve_kill_goblins_5:name": "边境巡逻",
  "quests:daily_ve_smith_copper:name": "熔炉不眠",
  "quests:q_ash_hunter:name": "灰原灭虫者",
  "quests:q_blackthorn_1:name": "深入黑荆棘林",
  "quests:q_blackthorn_2:description": "深入黑荆棘林，直抵树根下的古冢，击败 25 只扭曲根须怪。",
  "quests:q_blackthorn_2:name": "扭曲的深处",
  "quests:q_boar_hunter:description": "在牧野斩杀 15 头野猪。没了栅栏与牧人，它们养成了自己的习性，余烬堡需要它们的兽皮。",
  "quests:q_boar_hunter:name": "狂野狩猎",
  "quests:q_crypt_1:name": "陨落者之骨",
  "quests:q_crypt_2:name": "不屈之死者",
  "quests:q_crypt_3:name": "冰封寂静",
  "quests:q_dire_wolf_hunt:name": "荒野之恐",
  "quests:q_fighter_1:description": "累计击败 75 名敌人。血与汗铸就余烬堡所需的斗士。",
  "quests:q_fighter_1:name": "老练斗士",
  "quests:q_fighter_2:description": "累计砍倒 200 名敌人。仆从们已开始记住你的名字。",
  "quests:q_fighter_2:name": "坚毅战士",
  "quests:q_fighter_3:description": "累计击败 500 名敌人。每一个倒下的敌人，都是灰烬永远无法收录的一笔。",
  "quests:q_fighter_3:name": "百战老兵",
