  // ── New Haven / Encampment (0.3.0, Task #358): 15 Gebäude-Namen + Flavor ──
  "campBuildings:camp_townhall:name": "议事厅",
  "campBuildings:camp_townhall:description": "起初只是一间摆着桌子的小屋，后来成了带钟的房子：听见钟声的人就知道，New Haven 有人在做决定。",
  "campBuildings:camp_watchtower:name": "瞭望塔",
  "campBuildings:camp_watchtower:description": "只要上面有人守望，下面的活计就不会停。",
  "campBuildings:camp_storehouse:name": "仓房",
  "campBuildings:camp_storehouse:description": "架在石桩上，好让潮气和老鼠都进不去。沃斯送来了图纸，还叮嘱把一切都清点两遍。",
  "campBuildings:camp_scrivener_tent:name": "书记帐",
  "campBuildings:camp_scrivener_tent:description": "夜里写下的事，清晨就无须再作决定。",
  "campBuildings:camp_fishing_hut:name": "渔夫小屋",
  "campBuildings:camp_fishing_hut:description": "只要你坐得够静，浅滩给你的就不止是通路。",
  "campBuildings:camp_sawpit:name": "锯木坑",
  "campBuildings:camp_sawpit:description": "一人在上，一人在下满身锯末；无论如何，出来的都是梁木。",
  "campBuildings:camp_mine_adit:name": "矿道口",
  "campBuildings:camp_mine_adit:description": "山坡从不白给，但它总会给。",
  "campBuildings:camp_seed_garden:name": "育种园",
  "campBuildings:camp_seed_garden:description": "这片土地久未长出好东西；如今正重新学着信任。",
  "campBuildings:camp_fence_tent:name": "销赃帐",
  "campBuildings:camp_fence_tent:description": "没人问货是从哪来的。这正是这门生意。",
  "campBuildings:camp_workyard:name": "工坊场",
  "campBuildings:camp_workyard:description": "一条条工凳挤在同一张篷布下：邻座帮忙扶着钳子，每门手艺都更快。",
  "campBuildings:camp_smelter:name": "熔炉",
  "campBuildings:camp_smelter:description": "炉火不分工时：进去的东西终会化作锭条出来，有没有人看着都一样。",
  "campBuildings:camp_smokehouse:name": "熏房",
  "campBuildings:camp_smokehouse:description": "烟是边域里最有耐心的厨子。",
  "campBuildings:camp_trophy_wall:name": "战利品墙",
  "campBuildings:camp_trophy_wall:description": "布伦娜为首级付钱；这面墙记得它们都已送到。",
  "campBuildings:camp_warden_shrine:name": "静默者神龛",
  "campBuildings:camp_warden_shrine:description": "无像，无口，无手：只有一块立石，和或许有谁在倾听的可能。",
  "campBuildings:camp_trade_post:name": "贸易站",
  "campBuildings:camp_trade_post:description": "只要道路允许，穆克斯就会派车来；穆克斯说，价钱公道。",

