  "items:chronicle_ash_mark:name": "灰烬印记",
  "items:chronicle_crypt_lantern:name": "墓穴提灯",
  "items:chronicle_tide_chain:name": "潮汐锁链",
  "items:chronicle_idol_eye_ring:name": "神像之眼戒指",
