  "items:kestrel_loop:name": "红隼戒指",
  "items:kestrel_loop:description": "以红隼的初级飞羽制成的细窄指环，仍带着狩猎后的一丝油光。",
  "items:hawkeye_gyre:name": "鹰眼戒指",
  "items:hawkeye_gyre:description": "镶着一片磨亮红宝石的戒指，切割成鹰隼警觉的眼形，能稳住拉弓的手。",
  "items:sinewbound_coil:name": "腱缚戒指",
  "items:sinewbound_coil:description": "以风干的腱绳缠绕在一块浸血的宝石上。据佩戴者所说，在弓弦松开前它会发出微弱的嗡鸣。",
  "items:windwidow_snare:name": "风寡妇印戒",
  "items:windwidow_snare:description": "得名于一位没有猎物能活着伤到她的女猎手。钻石的光芒总是微微偏斜，从不直射。",
  "items:blackfletch_nock:name": "黑羽戒指",
  "items:blackfletch_nock:description": "缟玛瑙嵌入战甲皮革，饰以黑羽以隐没于夜空。是弓手对剑士所佩缟玛瑙戒指的回应。",
  "items:ghostquiver_notch:name": "幽灵箭袋环",
  "items:ghostquiver_notch:description": "以岁月褪色的龙皮缠裹而成。佩戴者都说背上的箭袋似乎变轻了，其实从未如此。",
  "items:worldpiercer_barb:name": "穿世戒指",
  "items:worldpiercer_barb:description": "神石镶嵌于影皮之中，衬着以太金属指环。据说它曾用一支箭射穿了本不该有另一面的存在。",
  "items:longsight_cord:name": "远视绳坠",
  "items:longsight_cord:description": "穿着蓝宝石碎片的皮绳。侦察兵佩戴它，学会了信赖双眼胜过双腿。",
  "items:windwhisper_torc:name": "风语项环",
  "items:windwhisper_torc:description": "以鳞甲皮革制成、镶着红宝石的项环。骑手们发誓，它能在箭矢命中前一瞬，先传来它飞行的声音。",
  "items:harriers_clasp:name": "绞鹰锁链",
  "items:harriers_clasp:description": "以铆钉皮革穿着血石制成，得名于一种从不第二次扑空的猛禽。",
  "items:kitehunter_collar:name": "猎鸢者坠饰",
  "items:kitehunter_collar:description": "钻石镶嵌于铆钉皮革与秘银丝之中。即使全力奔跑也稳如磐石。",
  "items:gloomfletch_choker:name": "暗羽护符",
  "items:gloomfletch_choker:description": "缟玛瑙嵌于暗色战甲皮革之中，饰以仿佛吞噬周遭光线的羽毛。是弓手对缟玛瑙护符的回应。",
  "items:nightquarry_wreath:name": "夜猎锁链",
  "items:nightquarry_wreath:description": "虚空石以龙皮与黑化铁缠绕而成。月下猎得的战利品，白日看来总不复相同。",
  "items:deadeye_reliquary:name": "死眼圣匣",
  "items:deadeye_reliquary:description": "神石圣匣镶嵌于影皮与以太金属之中，封存着一位从不需要第二支箭的女弓手最后的瞄准。",

  // ── Schmuck-Rework Welle 3 (29.08.2026): Reihe Magie ────────────────────────────────────────
  "actions:craft_emberglass_loop:name": "打造余烬玻璃戒指",
  "actions:craft_hollowlight_seal:name": "打造空明印戒",
