  "actions:craft_godgem_reliquary:name": "打造神晶圣匣",
  "items:emberglass_loop:name": "余烬玻璃戒指",
  "items:emberglass_loop:description": "火焰碎片镶嵌于因经年热力而泛琥珀色的玻璃之后。尚未施法，便已温暖了持有者的手。",
  "items:hollowlight_seal:name": "空明印戒",
  "items:hollowlight_seal:description": "以太碎片封存于秘银之中，即使在白昼也会微微发光。这是第一枚法师无需羞愧佩戴的戒指。",
  "items:nightwell_loop:name": "夜井戒指",
  "items:nightwell_loop:description": "缟玛瑙缠绕着一枚虚空碎片，其光芒源自比月光更深沉的黑暗。得名于一口从未被火把照亮过的井。",
  "items:voidscribe_glyph:name": "虚空书写者腕环",
  "items:voidscribe_glyph:description": "虚空石上刻着一道符文，只要无人注视便会自行改写。佩戴者都学会了不去细读它。",
  "items:godsight_loop:name": "神视戒指",
  "items:godsight_loop:description": "神晶镶嵌于受祝福的白银之中，据说每次施法前都会向佩戴者展示一个真相。少有人说自己乐于见到那真相。",
  "items:ashcant_cord:name": "灰烬颂歌坠饰",
  "items:gravecall_sigil:name": "墓唤护符",
  "items:duskveil_wreath:name": "暮纱锁链",
  "items:duskveil_wreath:description": "缟玛瑙以符文矿石与幽灵织物包裹而成，据说无论佩戴到何处都会让房间略微黯淡。",
  "items:voidsong_locket:name": "虚空之歌护符",
  "items:voidsong_locket:description": "虚空石吊坠低吟着一个旁人无法听见的音符。施法者们发誓，它与自己的脉搏分毫不差地同步。",
  "items:godgem_reliquary:name": "神晶圣匣",
  "items:godgem_reliquary:description": "神晶圣匣以星辰织物交织而成，封存着一位从未需要第二面结界的施法者留下的最后结界。",

  // ── Schmuck-Rework Welle 4 (29.08.2026): Nahkampf-Amulette + Fundstücke ─────────────────────
