  "actions:craft_warcrown_reliquary:name": "打造战冠圣匣",
  "items:gorecrown_locket:name": "血冠坠饰",
  "items:gorecrown_locket:description": "血石镶嵌于墓钢与战皮之中，据说记得佩戴者活着走出的每一场战斗。",
  "items:ironvow_collar:name": "铁誓锁链",
  "items:ironvow_collar:description": "钻石以秘银丝双重捆绑，为立誓要活下去的战士所佩戴。",
  "items:reavers_torc:name": "掠夺者项环",
  "items:reavers_torc:description": "缟玛瑙双重镶嵌于符文矿石中，取自一位从不让敌人选择战场的掠夺者。",
  "items:bloodiron_locket:name": "血铁吊坠",
  "items:warcrown_reliquary:name": "战冠圣匣",
  "items:warcrown_reliquary:description": "神晶圣匣双重镶嵌于神铁之中，封存着一位从未需要举起它来自卫的军阀的王冠。",
  "items:cutthroat_loop:name": "割喉者之戒",
  "items:cutthroat_loop:description": "以豺狼之牙制成的戒指，为等待伤口裂开才出手的猎人所佩戴。奖励终结一切的一击。",
  "items:firstlight_seal:name": "初光印戒",
  "items:firstlight_seal:description": "取自锻炉之火最初的余烬打造而成。每场战斗都在第一击中分出胜负，否则便根本不会分出。",
  "items:tidewrack_collar:name": "潮痕锁链",
  "items:hollowmarch_notch:name": "空寂长征环",
  "items:hollowmarch_notch:description": "在穿越空寂大厅的无尽行军中被磨得光滑。每一步不停歇的前进都会使其变得更强。",
  "items:ashenvow_locket:name": "灰烬誓言坠饰",
  "items:ashenvow_locket:description": "在燃烧的煤炭上立下的誓言，即使火焰熄灭也依然坚守。在肺中只剩最后一口气时打出最重的一击。",
  "items:rimeheart_locket:name": "霜心吊坠",
  "items:rimeheart_locket:description": "被一位从未感受过寒冷的冰法师彻底冻结。惩罚一切已经慢得无法逃脱的目标。",
  "items:thornwarden_seal:name": "荆棘守卫印戒",
  "items:thornwarden_seal:description": "由一位将每次受创都化为下一次反击的守卫雕刻而成。奖励仍然屹立不倒的战士。",
  "items:sunder_crown:name": "裂晶王冠",
  "items:sunder_crown:description": "碎裂自一顶未曾统治任何单一王国的王冠，为同时精通所有技艺者所佩戴。一击致命之时，若它可能来自任何方向，便打得更狠。",

