  "items:oreveined_hoop:description": "镶嵌着蓝宝石碎片，覆于未经打磨的矿石之上，仍隐约带着采出矿脉的气味。偶尔能让一次收获翻倍。",
  "items:thriftcut_cinch:name": "节俭裁皮戒指",
  "items:thriftcut_cinch:description": "钻石镶嵌于秘银之中，被从不浪费一寸兽皮的双手磨得光滑。",
  "items:steadhand_cuff:name": "稳手戒指",
  "items:steadhand_cuff:description": "缟玛瑙以触碰过虚空的丝线束紧。在最要紧的那一刻，让手不再颤抖。",
  "items:harvestward_clutch:name": "护穑锁链",
  "items:harvestward_clutch:description": "虚空石锁链以星辰织物包裹，即使在隆冬也如翻耕过的泥土般温暖。",
