  // codex:2026-10-17T15:00:00+02:00 — 1.3.0 E1/E2: offene Götzenhalle, Getilgte Kapelle, Chronik Band 2 Kapitel 22–27 (Texte nach design/lore/band2-auftakt-1.3.0.md §5).
  "monsters:idol_husk:name": "神像空壳",
  "monsters:skarn_whelp:name": "斯卡恩幼崽",
  "monsters:forsaken_servant:name": "被弃的仆从",
  "monsters:idol_priest:name": "神像祭司",
  "monsters:prayer_eater:name": "噬祷者",
  "monsters:wreath_bearer:name": "花环持者",
  "monsters:siege_idol:name": "攻城神像",
  "monsters:the_expunger:name": "抹除者",
  "monsters:dg_wreath_bearer:name": "花环持者",
  "monsters:dg_prayer_eater:name": "噬祷者",
  "dungeons:expunged_chapel:name": "被抹除的礼拜堂",
  "dungeons:expunged_chapel:waveMeta.0.name": "游行队列",
  "dungeons:expunged_chapel:waveMeta.1.name": "空缺",
  "dungeons:expunged_chapel:waveMeta.2.name": "抹除者",
  "quests:chronicle_22:name": "空荡的大厅",
  "quests:chronicle_23:name": "祝圣",
  "quests:chronicle_24:name": "神像所饮之物",
  "quests:chronicle_25:name": "花环",
  "quests:chronicle_25:loreText": "我曾在熔渣坑看着它们被浇铸，那时我还相信警告是一门职业。最初的神铁花环，由并非人类的双手引导。如今它们又出现了。花环持者肩并着肩，在长厅中列队行进，承载着被加在身上的东西，仿佛游行尚未结束。没有人告诉它们要去哪里。那从来就没有定下。你挡住了它们的路，它们便像造物那样倒下：毫无怨言，却声响震天。我端详碎片上的铸缝，直到手不再颤抖。造物完成之时，铸缝会被打磨掉。这些从未完成。这让我以一种我不愿解释的方式松了口气。",
  "quests:chronicle_26:name": "攻城之作",
  "quests:chronicle_26:loreText": "神像是他对抗天堂的攻城器械。德拉赞说出这句话时我便记下了，直到今天才明白他是字面意思。在大厅尽头，它们排成一列，向天空俯身，双臂被重铸成投掷之臂，未完成，也没有主人。它们本该击中的东西依旧沉默。我宁愿没有人完成它们。你将它们一个接一个推倒，当最后一个倒下时，它们身后的墙露了出来。一扇不在大厅任何图纸上的门，而图纸都在我手里。门后是一侧厢殿，那里的每一处铭文都被凿去了，干净利落，一行接一行。有人在这里工作过。我不认为他已经完工。",
  "quests:chronicle_27:name": "抹除者",
  "quests:chronicle_27:description": "肃清被抹除的礼拜堂，击倒抹除者：删削经文之物仍在劳作。",
  "quests:chronicle_27:loreText": "入口处的游行队列，其后的空缺，而在礼拜堂尽头：是他。你到来时，他没有抬头。他在凿刻。抹除者就是那只把第七位的名字从经文中割去的手，而它从未停止割削，因为一个名字若被放任，便可能归来。你击倒了他，而他的工作原样留下：满墙的空缺，全是同一个形状。我用手描过其中一处。它与祭司们祈祷所向的那处空缺正相吻合。我平实地写下这些，因为我无法用别的方式书写：第七位并未被遗忘。他是被刻意保持在遗忘之中。是谁想要这样，我所拥有的任何一本书里都没有记载，至少现在还没有。诸神之战并非始于诸神。它始于某人想要抹去的东西。",
  "achievements:ach_chapter_22:name": "空荡的大厅",
  "achievements:ach_chapter_22:description": "完成编年史第 22 章：空荡的大厅。",
  "achievements:ach_chapter_23:name": "祝圣",
  "achievements:ach_chapter_23:description": "完成编年史第 23 章：祝圣。",
  "achievements:ach_chapter_24:name": "神像所饮之物",
  "achievements:ach_chapter_24:description": "完成编年史第 24 章：神像所饮之物。",
  "achievements:ach_chapter_25:name": "花环",
  "achievements:ach_chapter_25:description": "完成编年史第 25 章：花环。",
  "achievements:ach_chapter_26:name": "攻城之作",
  "achievements:ach_chapter_26:description": "完成编年史第 26 章：攻城之作。",
  "achievements:ach_chapter_27:name": "刻意的遗忘",
