  "items:sentinel_coreblade:description": "一柄用陨落哨兵核心装甲锻成的巨剑，仍因残存的守护能量而微微嗡鸣。",
  "items:colossus_marrowaxe:description": "一块以石化髓骨凿成的巨大斧刃，总是劈向房间里最大的目标。",
  "items:wisp_kindled_bough:description": "一根沼泽木枝，疙瘩般的枝梢上仍燃着被困的鬼火。",
  "items:chitinshell_sparker:description": "一根以甲虫甲壳为芯的法杖，每次挥动都迸出静电火花。",
  "items:barrowsong_crook:description": "从墓丘诵唱者手中夺来的陵墓权杖，摸上去依旧冰冷。",
  "items:briarbound_conduit:description": "一枚被活荆棘缠绕的催化宝珠，嗡鸣着女巫残留的法力。",
  "items:voidherald_flightbow:description": "一把以虚空浸染的筋腱为弦的长弓，取自使者自己的圣物匣。",
  "items:voidhusk_deadeye:description": "一把包覆虚空壳甲的重型长弓，每次只为一记致命射击而造。",
