  "talentNodes:slayer.lore:name": "猎人学识",
  // claude:2026-10-30T18:46:25+01:00 — 1.4.2: Jägerkodex-Erzählsätze (talentNodes:<baum>.<knoten>:flavor).
  "talentNodes:slayer.tracking:flavor": "布伦娜读足迹，就像别人读信一样。",
  "talentNodes:slayer.trail:flavor": "霉运总有用完的时候。耐心不会。",
  "talentNodes:slayer.collar:flavor": "门边的挂钩上，又多了一副项圈。",
  "talentNodes:slayer.pace:flavor": "布伦娜按人头付钱，而且数得很快。",
  "talentNodes:slayer.spoils:flavor": "派你去追的野兽，身上总带着值得跑这一趟的东西。",
  "talentNodes:slayer.lore:flavor": "每一种都亲手杀过，你便知道它们各自会在哪里折断。",
  // claude:2026-10-18T12:00:00+02:00 — Narbenbuch (Prestige „Der Aschesturz“, Welle B2): Baum, Äste, Knoten.
  "talentTrees:prestige:name": "伤痕之书",
  "talentTrees:prestige:description": "守望者记录每一次烬落的书。在碎片祭坛获得的伤痕，会在这里化为此后每个周目的长久馈赠。",
  "talentBranches:prestige.legacy:name": "所留之物",
  "talentBranches:prestige.haste:name": "捷径",
  "talentBranches:prestige.might:name": "烙痕",
  "talentBranches:prestige.watch:name": "漫长守夜", // claude:2026-10-30T18:46:25+01:00 — 1.4.2
  "talentBranches:prestige.crown:name": "拱心石",
  "talentNodes:prestige.startingGold:name": "陪葬钱币",
  "talentNodes:prestige.startingGold:description": "每个新周目开始时拥有 {value} 金币。", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  "talentNodes:prestige.keepTools:name": "老茧",
  "talentNodes:prestige.keepTools:description": "你的所有工具都能在烬落中保留，并在仓库中等你。", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  "talentNodes:prestige.keepBankStacks:name": "埋藏的箱子",
  "talentNodes:prestige.keepEquipment:name": "传家宝",
  "talentNodes:prestige.earlyXp:name": "学徒岁月",
  "talentNodes:prestige.earlyXp:description": "80 级以下的技能经验提高 {value}。", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  "talentNodes:prestige.chronicleRecall:name": "熟悉的书页",
  "talentNodes:prestige.masteredXp:name": "第二天性",
  "talentNodes:prestige.dungeonRecall:name": "旧日之路",
  "talentNodes:prestige.maxHp:name": "疤痕组织",
  "talentNodes:prestige.maxHp:description": "最大生命值提高 {value}。", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  "talentNodes:prestige.damage:name": "伤痕之拳",
  "talentNodes:prestige.damage:description": "你造成的伤害提高 {value}。", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  "talentNodes:prestige.goldFind:name": "喜鹊之眼",
  "talentNodes:prestige.pointsBoost:name": "更深的一刀",
  "talentNodes:prestige.pointsBoost:description": "此后每次烬落从周目本身获得的伤痕提高 {value}，不计你的收藏。", // claude:2026-10-30T18:46:25+01:00 — 1.4.2 nur Wirkung, Erzählsatz in :flavor
  // claude:2026-10-30T18:46:25+01:00 — 1.4.2 Narbenbuch (Aschesturz 2.0): Erzählsätze aller Knoten, zwölf neue Knoten mit Name und Wirkung.
  "talentNodes:prestige.startingGold:flavor": "人们会给死者带上路费。你并没有死，但钱币总不碍事。",
  "talentNodes:prestige.keepTools:flavor": "双手不会忘记它们的工具。",
  "talentNodes:prestige.keepPurchases:name": "账已结清",
  "talentNodes:prestige.keepPurchases:description": "你的自动进食等级、自动增益解锁和所有购买的仓库格都能在烬落中保留。",
  "talentNodes:prestige.keepPurchases:flavor": "付过钱的，就一直算数。连灰烬也记着账。",
  "talentNodes:prestige.keepBankStacks:flavor": "埋起来的东西，从没见过火。",
  "talentNodes:prestige.keepSlayerPoints:name": "未断的踪迹",
  "talentNodes:prestige.keepSlayerPoints:description": "你的猎魔点数和代币有 {value} 能在烬落中保留。",
  "talentNodes:prestige.keepSlayerPoints:flavor": "猎人倒下了，踪迹却不会因此变冷。",
  "talentNodes:prestige.keepEquipment:flavor": "一件灰烬拿不走的东西。",
  "talentNodes:prestige.earlyXp:flavor": "学过一次的东西，第二次学得更快。",
  "talentNodes:prestige.chronicleRecall:flavor": "编年史不会把你已经活过的章节再读给你听。",
  "talentNodes:prestige.dungeonRecall:flavor": "你清理过一次的大门认得你。",
  "talentNodes:prestige.masteredXp:flavor": "你的双手仍记得该伸向哪里。",
  "talentNodes:prestige.actionSpeed:name": "熟练之手",
  "talentNodes:prestige.actionSpeed:description": "采集、制作和盗窃动作的耗时减少 {value}。",
  "talentNodes:prestige.actionSpeed:flavor": "第二次做的时候，再也不用别人教你怎么握。",
  "talentNodes:prestige.masteryXp:name": "精通余烬",
  "talentNodes:prestige.masteryXp:description": "精通经验提高 {value}。",
  "talentNodes:prestige.masteryXp:flavor": "精通从未随其他东西一起烧掉。它只是在等新的柴火。",
  "talentNodes:prestige.damage:flavor": "断过一次的指节，不会再断。",
  "talentNodes:prestige.maxHp:flavor": "疤痕组织不那么容易撕裂。",
  "talentNodes:prestige.goldFind:flavor": "你收集曾属于神像的东西，就像喜鹊收集银器。",
  "talentNodes:prestige.foodHeal:name": "余烬之血",
  "talentNodes:prestige.foodHeal:description": "食物为你恢复的生命提高 {value}。",
  "talentNodes:prestige.foodHeal:flavor": "流过灰烬的血，会接住别人给它的每一分温暖。",
  "talentNodes:prestige.rareDrop:name": "锐眼",
  "talentNodes:prestige.rareDrop:description": "战斗中的稀有掉落（1/500 或更稀有）几率提高 {value}。",
  "talentNodes:prestige.rareDrop:flavor": "那道闪光你见过。这一次，你知道该往哪里看。",
  "talentNodes:prestige.offlineHours:name": "长夜",
  "talentNodes:prestige.offlineHours:description": "你的离线时长增加 {value} 小时。",
  "talentNodes:prestige.offlineHours:flavor": "火只是烧得低了，并没有熄灭。你不在时，活计照常进行。",
  "talentNodes:prestige.workOrders:name": "渡鸦信使",
  "talentNodes:prestige.workOrders:description": "工作订单出现的频率提高 {value}。",
  "talentNodes:prestige.workOrders:flavor": "渡鸦记住了你的名字。从那以后，它们就再也不让你清静。",
  "talentNodes:prestige.huntTraps:name": "设陷猎人",
  "talentNodes:prestige.huntTraps:description": "狩猎时可用的陷阱栏位增加 {value} 个。",
  "talentNodes:prestige.huntTraps:flavor": "你布下过的每一个套索，都还留在你手上的某处。",
  "talentNodes:prestige.farmPlots:name": "种子窖",
  "talentNodes:prestige.farmPlots:description": "可用的田地增加 {value} 块。",
  "talentNodes:prestige.farmPlots:flavor": "有几粒种子，在整场大火中都保持干燥。",
  "talentNodes:prestige.campBuild:name": "营造大师",
  "talentNodes:prestige.campBuild:description": "New Haven 的建造耗时减少 {value}。",
  "talentNodes:prestige.campBuild:flavor": "对一个已经失去过一切的人，工匠们干活会更快。",
  "talentNodes:prestige.pointsBoost:flavor": "下一次坠落切得更深，留下的也更多。",
  "talentNodes:prestige.petEcho:name": "伙伴回响",
  "talentNodes:prestige.petEcho:description": "未装备的伙伴以其技能效果的 {value} 生效，而不是 25%。",
  "talentNodes:prestige.petEcho:flavor": "他们不再走在你身旁，却从未停止跟随。",
