  "items:gk_quarter_quiver_heroic:description": "里面每一支箭都登记在册，克罗格还指望收回。",
  "items:gk_quarter_quiver_mythic:name": "军需官箭袋",
  "items:gk_quarter_quiver_mythic:description": "里面每一支箭都登记在册，克罗格还指望收回。",
  "items:gk_pit_longbow:name": "唤群",
  "items:gk_pit_longbow:description": "弓弦嗡鸣如哨；从兽坑里应声而来的东西，带着毒。",
  "items:gk_pit_longbow_heroic:name": "唤群",
  "items:gk_pit_longbow_heroic:description": "弓弦嗡鸣如哨；从兽坑里应声而来的东西，带着毒。",
  "items:gk_pit_longbow_mythic:name": "唤群",
  "items:gk_pit_longbow_mythic:description": "弓弦嗡鸣如哨；从兽坑里应声而来的东西，带着毒。",
  "items:gk_pit_scimitar:name": "兽坑獠牙",
  "items:gk_pit_scimitar:description": "刀刃仿照乌什卡养大的第一头巨兽的獠牙锻成；它撕扯，而非切割。",
