  "items:gk_fel_staff:name": "借火法杖",
  "items:gk_fel_staff:description": "杖头的火焰没有烟，也没有影子。它从未被归还。",
  "items:gk_fel_staff_heroic:name": "借火法杖",
  "items:gk_fel_staff_heroic:description": "杖头的火焰没有烟，也没有影子。它从未被归还。",
  "items:gk_fel_staff_mythic:name": "借火法杖",
