  "items:gk_fel_wand:name": "烬舌",
  "items:gk_fel_wand:description": "一片被出借之火舔舐的神铁；它只用火说话。",
  "items:gk_fel_wand_heroic:name": "烬舌",
  "items:gk_fel_wand_heroic:description": "一片被出借之火舔舐的神铁；它只用火说话。",
  "items:gk_fel_wand_mythic:name": "烬舌",
  "items:gk_fel_wand_mythic:description": "一片被出借之火舔舐的神铁；它只用火说话。",
  "items:gk_fel_ring:name": "债主之戒",
  "items:gk_fel_ring:description": "吉尔加斯曾以它作火的质押。债主从未来取。",
  "items:gk_fel_ring_heroic:name": "债主之戒",
  "items:gk_fel_ring_heroic:description": "吉尔加斯曾以它作火的质押。债主从未来取。",
  "items:gk_fel_ring_mythic:name": "债主之戒",
  "items:gk_fel_ring_mythic:description": "吉尔加斯曾以它作火的质押。债主从未来取。",
  "items:gk_king_greatsword:name": "继承者之刃",
  "items:gk_king_greatsword:description": "边境最后一任队长的剑，被一个哥布林双手挥舞。它从没抱怨过。",
  "items:gk_king_greatsword_heroic:name": "继承者之刃",
  "items:gk_king_greatsword_heroic:description": "边境最后一任队长的剑，被一个哥布林双手挥舞。它从没抱怨过。",
  "items:gk_king_greatsword_mythic:name": "继承者之刃",
