  "items:gk_king_shortbow:name": "继承者王冠之弓",
  "items:gk_king_shortbow:description": "短得适合哥布林，硬得配得上边境；拉克祖尔坐上王座之前，就用它射箭。",
  "items:gk_king_shortbow_heroic:name": "继承者王冠之弓",
  "items:gk_king_shortbow_heroic:description": "短得适合哥布林，硬得配得上边境；拉克祖尔坐上王座之前，就用它射箭。",
  "items:gk_king_shortbow_mythic:name": "继承者王冠之弓",
