  "items:gk_king_scepter:name": "王座权杖",
  "items:gk_king_scepter:description": "和王冠一样，用边境城门的铁件锻成；它下过的命令比王冠还多。",
  "items:gk_king_scepter_heroic:name": "王座权杖",
